// Package stracelexer tokenizes ONE LINE of `strace -f --quiet=attach -y -s
// 4096` output with the repo's grammar-driven lexer.
//
// The syntax is not written here.  It is written in two grammar files,
//
//	code/grammars/strace/strace.tokens         the tokens of a line
//	code/grammars/strace/strace-string.tokens  the escapes inside "..." and <...>
//
// whose compiled data lives in grammar_data.go and string_grammar_data.go
// (generated by `grammar-tools compile-tokens`).  This package only compiles
// that data ONCE, at start-up, and exposes a per-line entry point.
//
// # Why per line
//
// A strace trace is a sequence of independent lines, and everything that spans
// lines (a call interrupted by another process's output and resumed later) is
// policy that belongs to the consumer.  A per-line lexer can run on any line in
// any order, so a consumer can lex lines in parallel, and a hostile trace can
// never make one token span two lines.
//
// # Total
//
// The grammar ends with ERR_* tokens that match whatever nothing else did, so
// TokenizeLine never fails on a line without a newline.  A consumer refuses a
// line by finding an ERR_* token (see FirstError).  Nothing here panics.
package stracelexer

import (
	"errors"
	"fmt"
	"strings"

	"github.com/adhithyan15/coding-adventures/code/packages/go/lexer"
)

// compiledLine and compiledString are built once, when the package loads.  A
// compile error would be a bug in the committed grammar data; it is kept (not
// panicked on) and returned from every call, and a test asserts it is nil.
var (
	compiledLine, errLine     = lexer.Compile(TokenGrammarData)
	compiledString, errString = lexer.Compile(StringTokenGrammarData)
)

// Compiled returns the compiled line grammar, so a consumer can assert
// properties of it (SlowRules, case sensitivity) at start-up.  It is shared and
// immutable.
func Compiled() (*lexer.Compiled, error) { return compiledLine, errLine }

// StringCompiled returns the compiled string-escape grammar.
func StringCompiled() (*lexer.Compiled, error) { return compiledString, errString }

// SlowRules lists the line grammar's rules that run on the regexp engine instead
// of the fast byte matchers.  It MUST be empty: a slow rule costs time that
// grows with the rest of the line, per token, which is a denial of service on a
// huge line.  The grammar file keeps it empty; a test and the consumer assert
// it.
func SlowRules() []string {
	if compiledLine == nil {
		return []string{"(grammar failed to compile)"}
	}
	return compiledLine.SlowRules()
}

// ErrNewline is returned for a line that contains a newline.  A line is what is
// BETWEEN newlines; the lexer's built-in newline token would otherwise be
// skipped silently by the parser.
var ErrNewline = errors.New("strace-lexer: line contains a newline")

// DefaultMaxLineBytes is the longest line TokenizeLine accepts: 1 MiB, the
// same as kiln's line limit.  The length is checked BEFORE lexing, so a huge
// line costs nothing.
const DefaultMaxLineBytes = 1 << 20

// ErrLineTooLong is returned for a line longer than the byte limit.
var ErrLineTooLong = errors.New("strace-lexer: line is longer than the byte limit")

// TokenizeLine is TokenizeLineMax with DefaultMaxLineBytes.
func TokenizeLine(line string) ([]lexer.Token, error) {
	return TokenizeLineMax(line, DefaultMaxLineBytes)
}

// TokenizeLineMax tokenizes one line (no trailing newline).  The result ends
// with an EOF token.  Token.Column is the 1-based BYTE column in line, so the
// raw text of any run of tokens is
// line[first.Column-1 : last.Column-1+len(last.Value)] (true for every token
// except an EOF, whose Value is empty).
//
// maxBytes <= 0 means DefaultMaxLineBytes.  It returns ErrLineTooLong for a
// longer line (checked before any lexing), ErrNewline for a line containing
// '\n', and the grammar's compile error if the committed grammar were broken.
// For anything else it succeeds, with ERR_* tokens marking what the grammar
// does not allow.
func TokenizeLineMax(line string, maxBytes int) ([]lexer.Token, error) {
	return TokenizeLineMaxInto(line, maxBytes, nil)
}

// TokenizeLineMaxInto tokenizes one line into caller-provided token storage.
// It has the same byte, newline, and grammar checks as TokenizeLineMax. On
// success the returned tokens borrow dst's storage when standard tokenization
// can reuse it; on error the returned slice is nil. The caller owns the
// storage and its lifetime. If dst is a shortened prefix of an older result,
// the caller must clear any truncated tail it wants to release.
func TokenizeLineMaxInto(line string, maxBytes int, dst []lexer.Token) ([]lexer.Token, error) {
	if errLine != nil {
		return nil, errLine
	}
	if maxBytes <= 0 {
		maxBytes = DefaultMaxLineBytes
	}
	if len(line) > maxBytes {
		return nil, ErrLineTooLong
	}
	if strings.IndexByte(line, '\n') >= 0 {
		return nil, ErrNewline
	}
	return compiledLine.TokenizeInto(line, dst)
}

// IsErrToken reports whether t is one of the grammar's ERR_* tokens.
func IsErrToken(t lexer.Token) bool { return strings.HasPrefix(t.TypeName, "ERR_") }

// FirstError returns the first ERR_* token of toks and its index.
func FirstError(toks []lexer.Token) (lexer.Token, int, bool) {
	for i, t := range toks {
		if IsErrToken(t) {
			return t, i, true
		}
	}
	return lexer.Token{}, -1, false
}

// Ambiguous reports whether the ERR_* token t is the kind the old hand-written
// scanner called an ambiguous path (a bad character or escape inside a -y
// annotation) rather than an unparsable line (an unterminated quote or
// annotation, a bad "<", a bad resume marker, a control character).
//
//   - ERR_ANNOT_BAD: a closed word<...> with an unescaped "<" or a control
//     character inside: ambiguous.
//   - ERR_ANNOT_OPEN: word<... with no ">": the old scanner stopped at the FIRST
//     problem, so it is ambiguous if the body already contains a bad character
//     or escape before the line ends, and unterminated otherwise.  The body is
//     decoded strictly to decide.
func Ambiguous(t lexer.Token) bool {
	switch t.TypeName {
	case "ERR_ANNOT_BAD":
		return true
	case "ERR_ANNOT_OPEN":
		i := strings.IndexByte(t.Value, '<')
		_, err := DecodeAnnotation(t.Value[i+1:])
		return err != nil
	}
	return false
}

// AnnotationBody returns the text between the angle brackets of an ANNOTATED
// token (`3</etc/passwd>` -> `/etc/passwd`, still escaped) and the text before
// them (`3`).
func AnnotationBody(t lexer.Token) (word, body string) {
	i := strings.IndexByte(t.Value, '<')
	return t.Value[:i], t.Value[i+1 : len(t.Value)-1]
}

// QuotedBody returns the text between the quotes of a QUOTED token (still
// escaped) and whether it ended with "..." (cut by -s).
func QuotedBody(t lexer.Token) (body string, truncated bool) {
	v := t.Value
	if strings.HasSuffix(v, `"...`) {
		return v[1 : len(v)-4], true
	}
	return v[1 : len(v)-1], false
}

// DecodeError says why a quoted-string or annotation body did not decode.
type DecodeError struct {
	Offset int    // byte offset in the body
	Reason string // what was wrong
}

func (e *DecodeError) Error() string {
	return fmt.Sprintf("strace-lexer: bad escape or character at body offset %d: %s", e.Offset, e.Reason)
}

// DecodeString strictly decodes the body of a quoted string (the text between
// the quotes).  The result is ARBITRARY BYTES: it can contain NUL and invalid
// UTF-8 (a string is data, "\\0" is a legal escape).  A consumer that uses it as
// a path must reject an embedded NUL and invalid UTF-8 itself.  It accepts exactly what the old scanner did: the simple
// escapes, \xHH, \O..\OOO with a value of at most 255, and any byte other than a
// control character, backslash or quote.  "<" and ">" are ordinary there.
func DecodeString(body string) ([]byte, error) { return decode(body, false) }

// DecodeAnnotation is DecodeString for the body of a -y annotation.  There
// "\<" and "\>" are escapes, and a raw "<" or ">" is refused (strace escapes
// them), while a raw quote is an ordinary character.
func DecodeAnnotation(body string) ([]byte, error) { return decode(body, true) }

func decode(body string, annotation bool) ([]byte, error) {
	if errString != nil {
		return nil, errString
	}
	// Fast path, by far the commonest: nothing to decode.  The grammar says a
	// run of ordinary bytes is one token; this is the same test without
	// building tokens.
	plain := true
	for i := 0; i < len(body); i++ {
		c := body[i]
		if c == '\\' || c == '"' || c == '<' || c == '>' || c < 0x20 || c == 0x7f {
			plain = false
			break
		}
	}
	if plain {
		return []byte(body), nil
	}
	toks, err := compiledString.Tokenize(body)
	if err != nil {
		return nil, err
	}
	out := make([]byte, 0, len(body))
	for _, t := range toks {
		off := t.Column - 1
		switch t.TypeName {
		case "EOF":
		case "CHARS":
			out = append(out, t.Value...)
		case "ESC_SIMPLE":
			out = append(out, simpleEscape(t.Value[1]))
		case "ESC_HEX":
			out = append(out, hexVal(t.Value[2])<<4|hexVal(t.Value[3]))
		case "ESC_OCT":
			v := 0
			for _, c := range t.Value[1:] {
				v = v*8 + int(c-'0')
			}
			if v > 255 {
				return nil, &DecodeError{off, "octal escape above 255"}
			}
			out = append(out, byte(v))
		case "ESC_ANGLE":
			if !annotation {
				return nil, &DecodeError{off, `\< and \> are only escapes in an annotation`}
			}
			out = append(out, t.Value[1])
		case "ERR_QUOTE":
			if !annotation {
				return nil, &DecodeError{off, "raw quote"}
			}
			out = append(out, '"')
		case "ERR_ANGLE":
			if annotation {
				return nil, &DecodeError{off, "raw angle bracket in an annotation"}
			}
			out = append(out, t.Value...)
		case "ERR_CTRL":
			return nil, &DecodeError{off, "control character"}
		default: // ERR_BSL
			return nil, &DecodeError{off, "invalid escape"}
		}
	}
	return out, nil
}

func simpleEscape(c byte) byte {
	switch c {
	case 'n':
		return '\n'
	case 't':
		return '\t'
	case 'r':
		return '\r'
	case 'a':
		return 7
	case 'b':
		return 8
	case 'f':
		return 12
	case 'v':
		return 11
	}
	return c // \" and \\
}

func hexVal(c byte) byte {
	switch {
	case c >= '0' && c <= '9':
		return c - '0'
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10
	}
	return c - 'A' + 10
}
